<div class="wp-block-wdl-paid-block-fv-10 paid-block-fv-10 min-h-pc-360px min-h-tb-320px min-h-sp-240px"><div class="fv-10_inner"><h1 class="ttl font_size_m" style="color:#063733"><span class="main" style="color:#063733">安心のために</span></h1><div class="inner_filter" style="background-color:#ffffff;border-color:#c9dcd7;border-width:1px;border-style:solid;border-radius:4px;box-shadow:0px 4px 12px 0px rgba(6,55,51,0.10)"></div></div><div class="filter" style="background-color:#dfe8e6;opacity:1"></div><picture class="bg_image"><source srcSet="" media="(max-width: 800px)"/><source srcSet="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/saas_security_1.webp" media="(min-width: 801px)"/><img src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/saas_security_1.webp" alt="" loading="eager" fetchpriority="high"/></picture></div>
