<!-- wp:wdl/lw-pr-custom-title-11 {"mainTitle":"やめたいと思ったときのこと","subTitle":"HOW TO LEAVE","headingLevel":2,"colorMain":"#0e5c55","colorMainText":"#ffffff","colorSubText":"#cfe6e2","borderRadius":4} -->
<div class="wp-block-wdl-lw-pr-custom-title-11 lw-pr-custom-title-11" style="--color-main:#0e5c55;--color-main-text:#ffffff;--color-sub-text:#cfe6e2;width:100%;margin:1em auto" id="kaiyaku"><h2 class="ttl" style="border-radius:4px"><span class="sub">HOW TO LEAVE</span><span class="main">やめたいと思ったときのこと</span></h2></div>
<!-- /wp:wdl/lw-pr-custom-title-11 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"align":"center","style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"16px","lineHeight":"2"},"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center has-text-color" style="color:#1f2b2a;font-size:16px;line-height:2;margin-top:28px;margin-bottom:24px">引き止めの電話はしません。手順をここに書いておきます。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-pr-step-8 {"stepNo":"01","bgGradient":"#0e5c55","colorNo":"#0e5c55","ulMaxWidth":900} -->
<div class="lw-pr-step-8"><div class="lw-step__inner" style="max-width:900px"><div class="lw-step__li" style="border-color:#0e5c55;--step-8-bdr-pc:10px;--step-8-bdr-sp:10px"><div class="lw-step__li_no" data-lw_font_set="Murecho" style="font-weight:600;color:#0e5c55">01</div><div class="lw-step__li_in" style="--step-8-li-in-pt-pc:0.6em;--step-8-li-in-pt-sp:0.6em"><!-- wp:heading {"level":3,"style":{"color":{"text":"#063733"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}}} -->
<h3 class="has-text-color" style="color:#063733;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:16px">画面から解約する</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#1f2b2a;font-size:16px;line-height:1.9">「設定」→「契約」→「解約する」で手続きが終わります。電話も書面も要りません。理由の入力も任意です。</p>
<!-- /wp:paragraph --></div></div></div></div>
<!-- /wp:wdl/lw-pr-step-8 -->
<!-- wp:wdl/lw-pr-step-8 {"stepNo":"02","bgGradient":"#0e5c55","colorNo":"#0e5c55","ulMaxWidth":900} -->
<div class="lw-pr-step-8"><div class="lw-step__inner" style="max-width:900px"><div class="lw-step__li" style="border-color:#0e5c55;--step-8-bdr-pc:10px;--step-8-bdr-sp:10px"><div class="lw-step__li_no" data-lw_font_set="Murecho" style="font-weight:600;color:#0e5c55">02</div><div class="lw-step__li_in" style="--step-8-li-in-pt-pc:0.6em;--step-8-li-in-pt-sp:0.6em"><!-- wp:heading {"level":3,"style":{"color":{"text":"#063733"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}}} -->
<h3 class="has-text-color" style="color:#063733;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:16px">その月の末日まで使える</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#1f2b2a;font-size:16px;line-height:1.9">解約した日ではなく、その月の末日まで使えます。日割りでの返金はありませんが、末日までは今までどおりお使いいただけます。</p>
<!-- /wp:paragraph --></div></div></div></div>
<!-- /wp:wdl/lw-pr-step-8 -->
<!-- wp:wdl/lw-pr-step-8 {"stepNo":"03","bgGradient":"#0e5c55","colorNo":"#0e5c55","ulMaxWidth":900} -->
<div class="lw-pr-step-8"><div class="lw-step__inner" style="max-width:900px"><div class="lw-step__li" style="border-color:#0e5c55;--step-8-bdr-pc:10px;--step-8-bdr-sp:10px"><div class="lw-step__li_no" data-lw_font_set="Murecho" style="font-weight:600;color:#0e5c55">03</div><div class="lw-step__li_in" style="--step-8-li-in-pt-pc:0.6em;--step-8-li-in-pt-sp:0.6em"><!-- wp:heading {"level":3,"style":{"color":{"text":"#063733"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}}} -->
<h3 class="has-text-color" style="color:#063733;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:16px">データを書き出す</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#1f2b2a;font-size:16px;line-height:1.9">お客様・予約・請求のすべてをCSVで書き出せます。書き出しは<strong>解約したあとも90日間できます</strong>（この間は無料です）。</p>
<!-- /wp:paragraph --></div></div></div></div>
<!-- /wp:wdl/lw-pr-step-8 -->
<!-- wp:wdl/lw-pr-step-8 {"stepNo":"04","bgGradient":"#0e5c55","colorNo":"#0e5c55","ulMaxWidth":900} -->
<div class="lw-pr-step-8"><div class="lw-step__inner" style="max-width:900px"><div class="lw-step__li" style="border-color:#0e5c55;--step-8-bdr-pc:10px;--step-8-bdr-sp:10px"><div class="lw-step__li_no" data-lw_font_set="Murecho" style="font-weight:600;color:#0e5c55">04</div><div class="lw-step__li_in" style="--step-8-li-in-pt-pc:0.6em;--step-8-li-in-pt-sp:0.6em"><!-- wp:heading {"level":3,"style":{"color":{"text":"#063733"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}}} -->
<h3 class="has-text-color" style="color:#063733;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:16px">90日で自動的に消える</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#1f2b2a;font-size:16px;line-height:1.9">90日たつとデータは自動で削除されます。それより早く消してほしい場合は、お申し出いただければ7日以内に削除し、完了をお知らせします。</p>
<!-- /wp:paragraph --></div></div></div></div>
<!-- /wp:wdl/lw-pr-step-8 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-custom-title-11 {"mainTitle":"困ったときの受付","subTitle":"SUPPORT","headingLevel":2,"colorMain":"#0e5c55","colorMainText":"#ffffff","colorSubText":"#cfe6e2","borderRadius":4} -->
<div class="wp-block-wdl-lw-pr-custom-title-11 lw-pr-custom-title-11" style="--color-main:#0e5c55;--color-main-text:#ffffff;--color-sub-text:#cfe6e2;width:100%;margin:1em auto" id="support"><h2 class="ttl" style="border-radius:4px"><span class="sub">SUPPORT</span><span class="main">困ったときの受付</span></h2></div>
<!-- /wp:wdl/lw-pr-custom-title-11 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"align":"center","style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"16px","lineHeight":"2"},"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center has-text-color" style="color:#1f2b2a;font-size:16px;line-height:2;margin-top:28px;margin-bottom:24px">メールは毎日受け付けています。<span class="lw-br on_500px"></span>電話はおみせプラン以上の方が対象です。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-pr-calendar-1 {"colorTableItemBd":"#c9dcd7","colorTableHeadItemBg":"#0e5c55","colorTableHeadItemText":"#ffffff","colorTableBodyItemText":"#1f2b2a","colorTableBodyItemFirstText":"#063733","headItems":["受付","月","火","水","木","金","土","日"],"bodyRows":[["メール（24時間受付）","○","○","○","○","○","○","○"],["電話 10:00 - 18:00","○","○","○","○","○","△","×"],["画面を一緒に見る相談","○","○","○","○","○","×","×"]]} -->
<div class="wp-block-wdl-lw-pr-calendar-1 lw-pr-calendar-1" style="--color-table-item-bd:#c9dcd7;--color-table-head-item-bg:#0e5c55;--color-table-head-item-text:#ffffff;--color-table-body-item-text:#1f2b2a;--color-table-body-item-first-text:#063733"><div class="wrap_table"><div class="table_head"><div class="item first" data-lw_font_set=""><span>受付</span></div><div class="item " data-lw_font_set=""><span>月</span></div><div class="item " data-lw_font_set=""><span>火</span></div><div class="item " data-lw_font_set=""><span>水</span></div><div class="item " data-lw_font_set=""><span>木</span></div><div class="item " data-lw_font_set=""><span>金</span></div><div class="item " data-lw_font_set=""><span>土</span></div><div class="item " data-lw_font_set=""><span>日</span></div></div><div class="table_body"><div class="item first" data-lw_font_set=""><span>メール（24時間受付）</span></div><div class="item " data-lw_font_set=""><span>○</span></div><div class="item " data-lw_font_set=""><span>○</span></div><div class="item " data-lw_font_set=""><span>○</span></div><div class="item " data-lw_font_set=""><span>○</span></div><div class="item " data-lw_font_set=""><span>○</span></div><div class="item " data-lw_font_set=""><span>○</span></div><div class="item " data-lw_font_set=""><span>○</span></div></div><div class="table_body"><div class="item first" data-lw_font_set=""><span>電話 10:00 - 18:00</span></div><div class="item " data-lw_font_set=""><span>○</span></div><div class="item " data-lw_font_set=""><span>○</span></div><div class="item " data-lw_font_set=""><span>○</span></div><div class="item " data-lw_font_set=""><span>○</span></div><div class="item " data-lw_font_set=""><span>○</span></div><div class="item " data-lw_font_set=""><span>△</span></div><div class="item " data-lw_font_set=""><span>×</span></div></div><div class="table_body"><div class="item first" data-lw_font_set=""><span>画面を一緒に見る相談</span></div><div class="item " data-lw_font_set=""><span>○</span></div><div class="item " data